// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory tos, uint v) public {
        // restrict no constraints beyond the contract's require, letting the fuzzer explore the input space
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        bool success;
        try c.transfer(from, caddress, tos, v) returns (bool result) {
            success = true;
            // The return value must be true for any call that does not revert
            assertTrue(result);
        } catch {
            success = false;
        }
        // If it reverted, the invariant is vacuously true; the bug only triggers on non-reverting calls
        // The assertTrue inside the try block is the only assertion.
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address[] memory tos, uint256 v) public payable {
        require(tos.length > 1);
        bool reverted; try c.transfer(from, token, tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted || tos.length == 1);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 1);
        bool reverted;
        try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted ? _tos.length <= 1 : true);
    }
    receive() external payable {}
}

